def evaluate(board):
    """Score from side-to-move perspective."""
    mg = [0, 0]; eg = [0, 0]; phase = 0
    pm = board.piece_map()
    for sq, p in pm.items():
        c = 0 if p.color else 1
        mg[c] += MG[(p.piece_type, p.color, sq)]
        eg[c] += EG[(p.piece_type, p.color, sq)]
        phase += phase_inc[p.piece_type]
    # bishop pair bonus
    wb = len(board.pieces(chess.BISHOP, True)); bb = len(board.pieces(chess.BISHOP, False))
    if wb >= 2: mg[0] += 30; eg[0] += 50
    if bb >= 2: mg[1] += 30; eg[1] += 50
    # simple pawn structure: doubled/passed pawns
    wp = board.pieces(chess.PAWN, True); bp = board.pieces(chess.PAWN, False)
    for f in range(8):
        wf = sum(1 for s in wp if chess.square_file(s) == f)
        bf = sum(1 for s in bp if chess.square_file(s) == f)
        if wf > 1: mg[0] -= 10*(wf-1); eg[0] -= 20*(wf-1)
        if bf > 1: mg[1] -= 10*(bf-1); eg[1] -= 20*(bf-1)
    for s in wp:
        f = chess.square_file(s); r = chess.square_rank(s)
        if not any(chess.square_rank(b) > r and abs(chess.square_file(b)-f) <= 1 for b in bp):
            mg[0] += 5*r; eg[0] += 15*r
    for s in bp:
        f = chess.square_file(s); r = chess.square_rank(s)
        if not any(chess.square_rank(b) < r and abs(chess.square_file(b)-f) <= 1 for b in wp):
            mg[1] += 5*(7-r); eg[1] += 15*(7-r)
    # mobility (cheap approx): number of legal-ish attacks for knights/bishops/rooks/queens
    if phase > 24: phase = 24
    mgs = mg[0]-mg[1]; egs = eg[0]-eg[1]
    score = (mgs*phase + egs*(24-phase)) // 24
    # tempo
    return score if board.turn else -score

MATE = 100000
piece_val = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}

class Searcher:
    def __init__(self):
        self.tt = {}
        self.nodes = 0
        self.stop_time = None
        self.killers = {}
        self.history = {}

    def order_moves(self, board, moves, tt_move, ply):
        scored = []
        killers = self.killers.get(ply, ())
        for m in moves:
            s = 0
            if m == tt_move:
                s = 10_000_000
            elif board.is_capture(m):
                victim = board.piece_type_at(m.to_square)
                if victim is None: victim = chess.PAWN  # en passant
                attacker = board.piece_type_at(m.from_square)
                s = 1_000_000 + piece_val[victim]*10 - piece_val[attacker]//10
            elif m.promotion:
                s = 900_000
            elif m in killers:
                s = 800_000
            else:
                s = self.history.get((board.turn, m.from_square, m.to_square), 0)
            scored.append((s, m))
        scored.sort(key=lambda x: -x[0])
        return [m for _, m in scored]

    def quiesce(self, board, alpha, beta, depth=0):
        self.nodes += 1
        stand = evaluate(board)
        if stand >= beta:
            return stand
        if alpha < stand:
            alpha = stand
        if depth > 8:
            return stand
        caps = [m for m in board.legal_moves if board.is_capture(m) or m.promotion == chess.QUEEN]
        # MVV-LVA
        def key(m):
            v = board.piece_type_at(m.to_square) or chess.PAWN
            a = board.piece_type_at(m.from_square)
            return -(piece_val[v]*10 - piece_val[a]//10)
        caps.sort(key=key)
        for m in caps:
            # delta pruning
            v = board.piece_type_at(m.to_square)
            gain = piece_val[v] if v else 100
            if m.promotion: gain += 800
            if stand + gain + 200 < alpha:
                continue
            board.push(m)
            score = -self.quiesce(board, -beta, -alpha, depth+1)
            board.pop()
            if score >= beta:
                return score
            if score > alpha:
                alpha = score
        return alpha

    def search(self, board, depth, alpha, beta, ply, allow_null=True):
        self.nodes += 1
        if (self.nodes & 2047) == 0 and time.time() > self.stop_time:
            raise TimeoutError
        if ply > 0:
            if board.is_repetition(2) or board.halfmove_clock >= 100:
                return 0
            if board.is_insufficient_material():
                return 0
        alpha_orig = alpha
        key = board._transposition_key()
        tt_move = None
        entry = self.tt.get(key)
        if entry is not None:
            tt_depth, tt_score, tt_flag, tt_move = entry
            if tt_depth >= depth and ply > 0:
                if tt_flag == 0:
                    return tt_score
                elif tt_flag == 1 and tt_score > alpha:
                    alpha = tt_score
                elif tt_flag == 2 and tt_score < beta:
                    beta = tt_score
                if alpha >= beta:
                    return tt_score
        in_check = board.is_check()
        if depth <= 0 and not in_check:
            return self.quiesce(board, alpha, beta)
        if depth <= 0:
            depth = 1
        moves = list(board.legal_moves)
        if not moves:
            if in_check:
                return -MATE + ply
            return 0
        # null move pruning
        if allow_null and not in_check and depth >= 3 and ply > 0 and beta < MATE - 1000:
            has_big = any(board.pieces(pt, board.turn) for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN))
            if has_big:
                board.push(chess.Move.null())
                score = -self.search(board, depth - 3, -beta, -beta + 1, ply + 1, False)
                board.pop()
                if score >= beta:
                    return beta
        moves = self.order_moves(board, moves, tt_move, ply)
        best = -MATE - 1
        best_move = None
        for i, m in enumerate(moves):
            board.push(m)
            gives_check = board.is_check()
            reduce = 0
            if i >= 4 and depth >= 3 and not in_check and not gives_check and not board.is_capture(m) and not m.promotion:
                reduce = 1
            if i == 0:
                score = -self.search(board, depth - 1, -beta, -alpha, ply + 1)
            else:
                score = -self.search(board, depth - 1 - reduce, -alpha - 1, -alpha, ply + 1)
                if score > alpha and (reduce or score < beta):
                    score = -self.search(board, depth - 1, -beta, -alpha, ply + 1)
            board.pop()
            if score > best:
                best = score
                best_move = m
            if score > alpha:
                alpha = score
            if alpha >= beta:
                if not board.is_capture(m):
                    k = self.killers.setdefault(ply, [])
                    if m not in k:
                        k.insert(0, m)
                        if len(k) > 2: k.pop()
                    hk = (board.turn, m.from_square, m.to_square)
                    self.history[hk] = self.history.get(hk, 0) + depth*depth
                break
        flag = 0
        if best <= alpha_orig: flag = 2
        elif best >= beta: flag = 1
        self.tt[key] = (depth, best, flag, best_move)
        return best

    def best_move(self, board, time_limit, max_depth=20, log=sys.stderr):
        self.stop_time = time.time() + time_limit
        self.nodes = 0
        self.killers = {}
        best = None
        moves = list(board.legal_moves)
        if len(moves) == 1:
            return moves[0], 0, 1
        start = time.time()
        depth_reached = 0
        for depth in range(1, max_depth + 1):
            try:
                score = self.search(board, depth, -MATE - 1, MATE + 1, 0)
                entry = self.tt.get(board._transposition_key())
                if entry and entry[3] is not None:
                    best = entry[3]
                depth_reached = depth
                elapsed = time.time() - start
                print(f"depth {depth} score {score} best {best} nodes {self.nodes} time {elapsed:.1f}", file=log, flush=True)
                if abs(score) > MATE - 1000:
                    break
                # don't start a new iteration if likely no time
                if elapsed > time_limit * 0.4:
                    break
            except TimeoutError:
                break
        if best is None:
            best = moves[0]
        return best, score if depth_reached else 0, depth_reached

if __name__ == "__main__":
    b = chess.Board(sys.argv[1] if len(sys.argv) > 1 else chess.STARTING_FEN)
    s = Searcher()
    m, sc, d = s.best_move(b, float(sys.argv[2]) if len(sys.argv) > 2 else 10)
    print(m, sc, d)
