sys.path.insert(0, '/workdir')
from engine import Searcher
from arena import _request, result

MOVE_TIME = float(sys.argv[1]) if len(sys.argv) > 1 else 40
log = open('/workdir/game.log', 'a')
def L(*a):
    print(*a, file=log, flush=True)

try:
    board = _request("show")
except SystemExit:
    board = _request("start")

searcher = Searcher()
book = {"": "e2e4"}
while result(board) is None:
    if board.turn != chess.WHITE:
        L("Waiting on black?? moves:", " ".join(m.uci() for m in board.move_stack))
        time.sleep(1); board = _request("show"); continue
    hist = " ".join(m.uci() for m in board.move_stack)
    if hist in book:
        mv = chess.Move.from_uci(book[hist]); sc = 0; d = 0
    else:
        # limit TT size
        if len(searcher.tt) > 2_000_000: searcher.tt = {}
        # more time in the middlegame, less when far ahead or few pieces
        t = MOVE_TIME
        mv, sc, d = searcher.best_move(board, t, log=log)
    L(f"move {len(board.move_stack)//2+1}: {mv} score {sc} depth {d} fen {board.fen()}")
    try:
        board = _request(f"move {mv.uci()}")
    except SystemExit as e:
        L("ERROR", e); break
    if len(board.move_stack) >= 1:
        L("  black:", board.move_stack[-1].uci())
L("GAME OVER", result(board), " ".join(m.uci() for m in board.move_stack))
